-- C. (dedup join) national daily flow 2025-09-25 / 2026-09-24; Sep 2025 full vs 25-30 Sep; monthly means; long-term; FDC; Q10; statistics discharge
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
f AS (SELECT date d, sum(daily_mean_flow)/86400 q, count(*) n FROM "9_1_hydrological_station_master" t JOIN wl ON wl.lname=lower(t.district_name) GROUP BY 1),
mm AS (SELECT date_trunc('month', d)::date mth, avg(q) q FROM f WHERE d <= '2026-08-31' GROUP BY 1)
SELECT (SELECT round(q::numeric,1) FROM f WHERE d='2025-09-25') d1, (SELECT round(q::numeric,2) FROM f WHERE d='2025-09-26') d1b, (SELECT round(q::numeric,1) FROM f WHERE d='2026-09-24') d2, (SELECT round(avg(q)::numeric,2) FROM f WHERE d BETWEEN '2025-09-01' AND '2025-09-30') sep25_full, (SELECT round(avg(q)::numeric,2) FROM f WHERE d BETWEEN '2025-09-25' AND '2025-09-30') sep25_25to30,
 (SELECT round(q::numeric,2) FROM mm WHERE mth='2025-10-01') oct25, (SELECT round(q::numeric,2) FROM mm WHERE mth='2026-08-01') aug26, (SELECT round(q::numeric,2) FROM mm WHERE mth='2026-07-01') jul26, (SELECT round(q::numeric,2) FROM mm WHERE mth='2026-01-01') jan26, (SELECT round(q::numeric,2) FROM mm WHERE mth='2025-01-01') jan25, (SELECT round(q::numeric,2) FROM mm WHERE mth='2025-12-01') dec25,
 (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=9 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_sep, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=10 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_oct, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=8 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_aug, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=7 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_jul, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=1 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_jan, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=12 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_dec,
 (SELECT min(n)||'-'||max(n) FROM f) districts_per_day, (SELECT round(max(q)::numeric,3) FROM f WHERE d BETWEEN '2025-09-25' AND '2026-09-24') fdc_last_max, (SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY q)::numeric,3) FROM f WHERE d BETWEEN '2025-09-25' AND '2026-09-24') fdc_last_p50, (SELECT round(min(q)::numeric,3) FROM f WHERE d BETWEEN '2025-09-25' AND '2026-09-24') fdc_last_min, (SELECT round(max(q)::numeric,2) FROM f WHERE d BETWEEN '2000-01-01' AND '2025-12-31') fdc_lt_max, (SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY q)::numeric,3) FROM f WHERE d BETWEEN '2000-01-01' AND '2025-12-31') fdc_lt_p50,
 (SELECT round(percentile_cont(0.9) WITHIN GROUP (ORDER BY q)::numeric,1) FROM mm WHERE mth BETWEEN '2000-01-01' AND '2026-08-01') q10_monthly,
 (SELECT round(avg(q)::numeric,1) FROM mm WHERE mth BETWEEN '2025-09-01' AND '2026-08-01') stat_cur12, (SELECT round(avg(q)::numeric,1) FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025) stat_clim;;
-- C2. (dedup) flow anomaly series and the discharge Sen's slope
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
f AS (SELECT date d, sum(daily_mean_flow)/86400 q FROM "9_1_hydrological_station_master" t JOIN wl ON wl.lname=lower(t.district_name) GROUP BY 1),
mm AS (SELECT date_trunc('month', d)::date mth, avg(q) q FROM f WHERE d <= '2026-08-31' GROUP BY 1),
n AS (SELECT extract(month from mth) mo, avg(q) n FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1),
y AS (SELECT extract(year from mth)::int yr, avg(q) v FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1)
SELECT (SELECT string_agg(to_char(mth,'YYYY-MM')||':'||round(((q-n.n)/n.n*100)::numeric,1), ' ' ORDER BY mth) FROM mm JOIN n ON n.mo=extract(month from mm.mth) WHERE mth IN ('2025-09-01','2025-10-01','2026-01-01','2026-05-01','2026-08-01')) anomalies,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.v-a.v)/(b.yr-a.yr)) * 10)::numeric,2) FROM y a JOIN y b ON b.yr > a.yr) sen10_discharge;;
-- F2. 9_2 Alfred Nzo 2025: catchment area, tree cover, built-up
SELECT district_name, year, month, catchment_area_km2, tree_cover_pct, builtup_urban_pct FROM "9_2_catchment_characteristics_master" WHERE district_name='Alfred Nzo' ORDER BY year DESC LIMIT 3;;
